div.style:
display: grid;
                                    grid-template-columns: repeat(3, 1fr);
                                    grid-auto-rows: 36mm;
                                    gap: 0;
                                    width: 210mm;
                                    page-break-inside: auto;

border: 0.5px dashed #ccc;
                                            padding: 4px 6px;
                                            display: flex;
                                            flex-direction: column;
                                            justify-content: center;
                                            page-break-inside: avoid;
                                            overflow: hidden;

font-size: 9px;
                                                font-weight: bold;
                                                text-transform: uppercase;
                                                color: #666;
                                                line-height: 1;

font-size: 11px;
                                                font-weight: 600;
                                                margin: 1px 0;
                                                white-space: nowrap;
                                                overflow: hidden;
                                                text-overflow: ellipsis;

font-size: 9px;
                                                color: #888;
                                                margin-bottom: 2px;
                                                white-space: nowrap;
                                                overflow: hidden;
                                                text-overflow: ellipsis;

font-size: 8px;
                                                text-align: center;
                                                font-family: monospace;
                                                margin-top: 1px;

t.t-value:
[{
                   'kind': 'PRODUCT',
                   'title': p.name,
                   'subtitle': 'SKU: ' + (p.default_code or '-'),
                   'barcode': p.barcode,
               } for p in docs]

[{
                   'kind': (loc.wms_location_type or 'LOCATION').upper(),
                   'title': loc.display_name,
                   'subtitle': loc.complete_name,
                   'barcode': loc.barcode,
               } for loc in docs]
